import { SKILLSET_MEMBERS } from "./generated/skillsets";

/**
 * The skill ids of a skillset declared in the catalog (catalog/skillsets/<id>), sorted. A skill joins
 * a set through the `sets` field of its template.json, so nothing in code lists skill names.
 * The data is generated by `pnpm catalog:build`.
 */
export function skillsetMembers(id: string): readonly string[] {
  const members = SKILLSET_MEMBERS[id];
  if (!members) throw new Error(`no skillset ${id} in the catalog; run pnpm catalog:build`);
  return members;
}
